// MARK: - Data Structures
// These will be generated by uniffi from Rust definitions

/// HRV metrics calculated from RR intervals
struct HrvMetrics {
    let sdnn: Double           // Standard deviation of NN intervals (ms)
    let rmssd: Double          // Root mean square of successive differences (ms)
    let pnn50: Double          // Percentage of NN intervals > 50ms different
    let meanRr: Double         // Mean RR interval (ms)
    let timestamp: String      // ISO8601 timestamp
}

/// Detected anomaly in biometric data
struct AnomalyEvent {
    let metricType: String
    let value: Double
    let timestamp: String      // ISO8601
    let severity: String       // "low", "moderate", "high"
}

/// Per-alter baseline statistics
struct BaselineStats {
    let alterId: String
    let metricType: String
    let mean: Double
    let stdDev: Double
    let percentile5: Double
    let percentile95: Double
    let sampleCount: Int
    let lastUpdated: String    // ISO8601
}

/// Sync result
struct SyncResult {
    let success: Bool
    let uploadedCount: Int
    let message: String
}

/// Rust error type
enum RustError: Error, LocalizedError {
    case processingFailed(String)
    case storageFailed(String)
    case syncFailed(String)
    case invalidData(String)
    
    var errorDescription: String? {
        switch self {
        case .processingFailed(let msg):
            return "Rust processing failed: \(msg)"
        case .storageFailed(let msg):
            return "Rust storage failed: \(msg)"
        case .syncFailed(let msg):
            return "Rust sync failed: \(msg)"
        case .invalidData(let msg):
            return "Invalid data: \(msg)"
        }
    }
}

// MARK: - Build Instructions
/*
 To generate actual uniffi bindings:
 
 1. Build Rust library:
    cd mobile/rust-core
    cargo build --release --target aarch64-apple-ios
 
 2. Generate Swift bindings:
    cargo run --bin uniffi-bindgen generate \
      --library target/debug/libhexus_core.dylib \
      --language swift \
      --out-dir ../ios/HeXuS/Generated
 
 3. Replace this stub file with generated bindings:
    - RustBridge.swift (generated)
    - hexus_coreFFI.h (generated C header)
    - hexus_core.modulemap (module map)
 
 4. Create XCFramework:
    xcodebuild -create-xcframework \
      -library target/aarch64-apple-ios/release/libhexus_core.a \
      -library target/aarch64-apple-ios-sim/release/libhexus_core.a \
      -output ../ios/Frameworks/HeXuSCore.xcframework
 
 5. Add XCFramework to Xcode project:
    - Drag HeXuSCore.xcframework into project
    - Embed & Sign in target settings
 */
